import gsap, { Power4 } from 'gsap';
import Canvas2D from '../base/Canvas2D';
import random from '../utils/random';

// random attractor params
const PARAMS = {
  a: 0.85, //rand.range(0, 2),
  b: 1.63, //rand.range(0, 2),
  c: 0.145,
  d: 0.11,
  noiseMultiplier: 5,
  noiseScale: 100,
  chaos: 0.15,
  particleCount: 1000,
  simulationTime: 3,
};

const rand = random();

export default class Experiment1 extends Canvas2D {
  constructor(options) {
    console.log(options);
    // const canvas = options.canvas;
    // const cursorOptions = {
    //   target: canvas.parentNode,
    //   hideElements: '.content, .about-box, .about-btn',
    // };
    super({ ...options });

    // this.description = `
    //   <h4>Noise Attractor</h4>
    //   <p>This is an experment based on this <a href="http://paulbourke.net/fractals/clifford/">clifford attractor</a> formula with some additional Simplex noise.</p>
    //   <p>Press Shift + D to bring up the debug panel.</p>
    // `;

    this.isRendering = true;
    this.canGenerate = false;

    this.pane.addInput(PARAMS, 'a', { min: 0, max: 2 });
    this.pane.addInput(PARAMS, 'b', { min: 0, max: 2 });
    this.pane.addInput(PARAMS, 'noiseMultiplier', { min: 0, max: 20 });
    this.pane.addInput(PARAMS, 'noiseScale', { min: 0, max: 500 });
    this.pane.addInput(PARAMS, 'chaos', { min: 0, max: 0.5 });
    this.pane.addInput(PARAMS, 'particleCount', {
      min: 0,
      max: 5000,
      step: 10,
    });
    this.pane.addInput(PARAMS, 'simulationTime', { min: 0, max: 10 });

    this.generateParticles(this.centerX, this.height * 0.7);
    this.start();
    // this.cursor.enable(false);
  }

  onMouseRelease() {
    if (this.canGenerate) {
      this.canGenerate = false;
      this.isRendering = true;
      this.generateParticles(this.mousePos[0], this.mousePos[1]);
      this.pane.refresh();
      // this.cursor.enable(false);
    }
  }

  animateTime() {
    this.simulationTime = {
      val: 0,
    };

    gsap.to(this.simulationTime, {
      duration: PARAMS.simulationTime / 2,
      val: PARAMS.simulationTime / 2,
      yoyo: true,
      repeat: 1,
      ease: Power4.easeInOut,
      onComplete: () => {
        // this.cursor.show();
        // this.cursor.enable(true);
        this.canGenerate = true;
        this.isRendering = false;
      },
    });
  }

  generateParticles(x, y) {
    this.particles = [];
    this.currentIteration = 0;
    this.ctx.clearRect(0, 0, this.width, this.height);

    this.animateTime();

    x = x || rand.range(0, this.width);
    y = y || rand.range(0, this.height);

    for (let i = 0; i < PARAMS.particleCount; i++) {
      this.particles.push({
        x,
        y,
        vx: 0,
        vy: 0,
      });
    }
  }

  getValue(x, y) {
    // clifford attractor
    // http://paulbourke.net/fractals/clifford/
    x = x - this.width * PARAMS.chaos;
    y = y - this.height * PARAMS.chaos;

    // attactor gives new x, y for old one.
    var x1 = Math.sin(PARAMS.a * y) + PARAMS.c * Math.cos(PARAMS.a * x);
    var y1 = Math.sin(PARAMS.b * x) + PARAMS.d * Math.cos(PARAMS.b * y);

    // find angle from old to new. that's the value.
    return Math.atan2(y1 - y, x1 - x);
  }

  render(p, time, i) {
    // this.ctx.fillStyle = '#fff';
    this.ctx.strokeStyle = '#BBD8F2';
    this.ctx.lineWidth = 0.1;
    this.ctx.globalAlpha = 0.3;

    // calculate new acceleration factor based on value direction
    // and add that to point's velocity
    var noise = rand.noise3D(
      p.x / PARAMS.noiseScale,
      p.y / PARAMS.noiseScale,
      i * 0.00015
    );

    var value = this.getValue(p.x, p.y) * (noise * PARAMS.noiseMultiplier);
    p.vx += Math.cos(value) * PARAMS.chaos;
    p.vy += Math.sin(value) * PARAMS.chaos;

    // move to current position
    this.ctx.beginPath();
    this.ctx.moveTo(p.x, p.y);

    // add velocity to position and line to new position
    p.x += p.vx * this.simulationTime.val;
    p.y += p.vy * this.simulationTime.val;

    this.ctx.lineTo(p.x, p.y);
    this.ctx.stroke();

    // apply some friction so point doesn't speed up too much
    p.vx *= 0.99;
    p.vy *= 0.99;

    // wrap around edges of screen
    if (p.x > this.width) p.x = 0;
    if (p.y > this.height) p.y = 0;
    if (p.x < 0) p.x = this.width;
    if (p.y < 0) p.y = this.height;
  }

  update(dt, time) {
    if (this.isRendering) {
      let i = 0;
      for (const p of this.particles) {
        this.render(p, time, i);
        i++;
      }
    }
  }
}
